	input	[7:0]  wraddress;
	input	  wren;
	output	[31:0]  q;
// MiSTer2MEGA65 (AExp Amiga 500 port), June 2026: the Altera-specific
// tri0/tri1 net declarations (simulation-only pull defaults for
